3	/// Wgpu device error scope for all filters that auto closes when exiting the scope unless it was already closed.
4	///
5	/// The expectation is that the scope is manually closed, but this construct is useful to not accidentally
6	/// leave the scope open when returning early from a function.
7	/// Opens scopes for all error types.
8	pub struct WgpuErrorScope {
9	    open: bool,
10	    device: Arc<wgpu::Device>,
11	}
12	
13	impl WgpuErrorScope {
14	    pub fn start(device: &Arc<wgpu::Device>) -> Self {
15	        device.push_error_scope(wgpu::ErrorFilter::Validation);
16	        device.push_error_scope(wgpu::ErrorFilter::OutOfMemory);
17	        device.push_error_scope(wgpu::ErrorFilter::Internal);
18	        Self {
19	            device: device.clone(),
20	            open: true,
21	        }
22	    }
23	
24	    pub fn end(
25	        mut self,
26	    ) -> [impl std::future::Future<Output = Option<wgpu::Error>> + Send + 'static; 3] {
27	        self.open = false;
28	        [
29	            self.device.pop_error_scope(),
30	            self.device.pop_error_scope(),
31	            self.device.pop_error_scope(),
32	        ]
33	    }
34	}
35	
36	impl Drop for WgpuErrorScope {
37	    fn drop(&mut self) {
38	        if self.open {
39	            drop(self.device.pop_error_scope());
40	            drop(self.device.pop_error_scope());
41	            drop(self.device.pop_error_scope());
42	        }
43	    }
44	}
