196	pub fn customize_eframe_and_setup_renderer(
197	    cc: &eframe::CreationContext<'_>,
198	) -> Result<(), re_renderer::RenderContextError> {
199	    re_tracing::profile_function!();
200	
201	    if let Some(render_state) = &cc.wgpu_render_state {
202	        use re_renderer::RenderContext;
203	
204	        // Put the renderer into paint callback resources, so we have access to the renderer
205	        // when we need to process egui draw callbacks.
206	        let paint_callback_resources = &mut render_state.renderer.write().callback_resources;
207	        let render_ctx = RenderContext::new(
208	            &render_state.adapter,
209	            render_state.device.clone(),
210	            render_state.queue.clone(),
211	            render_state.target_format,
212	        )?;
213	        paint_callback_resources.insert(render_ctx);
214	    }
215	
216	    re_ui::apply_style_and_install_loaders(&cc.egui_ctx);
